def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next(v for row in grid for v in row if v not in (0, 9) and
                 sum(r.count(v) for r in grid) > 0)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    shape = [(r-r0, c-c0) for r, c in points]
    out = [row[:] for row in grid]

    for top in range(h - (r1-r0+1) + 1):
        for left in range(w - (c1-c0+1) + 1):
            cells = [(top+dr, left+dc) for dr, dc in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = color
    return out
